    'For example smtp.gmail.com, smtp.seznam.cz, smtp-relay.brevo.com or smtp.vasedomena.cz.' => 'Zum Beispiel smtp.gmail.com, smtp.seznam.cz, smtp-relay.brevo.com oder smtp.ihredomain.de.',
